use serde_json::Value;

/// Rotates each character in the input string by 13 positions in the alphabet.
/// Non-alphabetic characters remain unchanged.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(solve(String::from("Hello, Z!")), String::from("Uryyb, M!"));
/// ```
fn solve(input: serde_json::Value) -> serde_json::Value {
    input.to_string()
        .chars()
        .map(|c| {
            if c.is_alphabetic() {
                let base = if c.is_uppercase() { 'A' } else { 'a' };
                (c as u8 - base + 13) % 26 + base
            } else {
                c
            }
        })
        .collect()
}

fn main() {
    // Example usage
    let input = serde_json::Value::from("Hello, Z!");
    let expected = serde_json::Value::from("Uryyb, M!");
    let result = solve(input);
    println!("{:?}", result);
}
```

